import sys

def main():
    import sys
    import math

    def min_packages(n, k):
        if n == 1:
            return 1
        if k >= n:
            return 1
        return math.ceil(n / k)

    t = int(sys.stdin.readline())
    results = []

    for _ in range(t):
        n, k = map(int, sys.stdin.readline().split())
        results.append(min_packages(n, k))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
